/** Synthetic local fixtures only. No provider, asset or licensing evidence. */
import { contextSnapshotSchema } from "../../src/domain/projects";
import { createIdentityReferenceSnapshot } from "../../src/domain/identity-references";
import {
  createIdentityInputSnapshot, getIdentityCurrentBasis, getIdentityFreshness, getIdentityReadiness, identitySystemVersionSchema,
  initialIdentityPreferences, projectIdentityOverviewSchema, refineIdentityComponent, selectIdentitySystem, summarizeIdentitySystem,
  type IdentityInputSnapshot, type IdentitySystemVersion, type ProjectIdentityOverview, type RefineIdentityComponent,
} from "../../src/domain/project-identity";

export const fixtureId = (n: number) => `60000000-0000-4000-8000-${String(n).padStart(12, "0")}`;
export const fixtureOwner = fixtureId(1), fixtureProject = fixtureId(2), fixtureAt = "2026-10-04T12:00:00Z";
export function fixtureInput(options: { projectRevision?: number; references?: number; maximal?: boolean; name?: string } = {}): IdentityInputSnapshot {
  const { projectRevision = 1, references: count = 1, maximal = false } = options;
  const scope = { ownerId: fixtureOwner, projectId: fixtureProject };
  const context = contextSnapshotSchema.parse({ description: maximal ? "😀".repeat(12000) : "Local test fixture: independent design studio", intake: { suppliedName: options.name ?? "Cedar" } });
  const referenceSnapshot = createIdentityReferenceSnapshot({ ...scope, referenceRevision: count ? 1 : 0, selectedReferenceCount: count, capturedAt: fixtureAt,
    selected: Array.from({ length: count }, (_, index) => ({
      reference: { id: fixtureId(1000 + index), ...scope, createdAt: fixtureAt,
        media: { ...scope, assetId: fixtureId(2000 + index), versionId: fixtureId(3000 + index), contentHash: fixtureBoards[0].sha256, purpose: "reference_media", mimeType: "image/png" },
        source: "user_supplied", attribution: { label: maximal ? "😀".repeat(240) : "Local fixture reference", creator: maximal ? "😀".repeat(240) : null,
          sourceUrl: maximal ? `https://example.test/${"a".repeat(2027)}` : null, rightsNote: maximal ? "😀".repeat(2000) : "Local test fixture; no license assertion" },
        relevantElements: ["colors", "typography"], tags: maximal ? Array.from({ length: 50 }, (_, tag) => `${String(tag).padStart(2, "0")}${"😀".repeat(78)}`) : [],
      }, reaction: { ...scope, referenceId: fixtureId(1000 + index), revision: 1, ensemble: true, elements: ["colors"], updatedAt: fixtureAt },
    })),
  });
  return createIdentityInputSnapshot({ ...scope, scope: "visual_identity_only", projectRevision, context, referenceSnapshot,
    preferencesRevision: 0, preferences: initialIdentityPreferences(context), capturedAt: fixtureAt });
}
export function fixtureSystem(input = fixtureInput(), index = 0): IdentitySystemVersion {
  const scope = { ownerId: input.ownerId, projectId: input.projectId }, systemId = fixtureId(10 + index);
  const direction = { direction: "Local fixture: restrained geometric forms.", usageNotes: "Keep proportions consistent." };
  return identitySystemVersionSchema.parse({ id: systemId, ...scope, createdAt: fixtureAt, input,
    source: { kind: "generated", batchId: fixtureId(400), jobId: fixtureId(401), stepKey: `identity.board.${index + 1}` },
    components: { logo: direction, colors: { swatches: [{ key: "primary", name: "Forest", hex: "#123456" }], usageNotes: "Use light backgrounds." },
      typography: { styles: [{ key: "body", role: "Body", family: "Local Fixture Family", weight: 400, style: "normal" }], usageNotes: "A specification, not an installed font." },
      graphics: direction, imagery: direction, composition: direction },
    board: { asset: { ...scope, assetId: fixtureId(100 + index), versionId: fixtureId(200 + index), contentHash: fixtureBoards[index % fixtureBoards.length]!.sha256, purpose: "brand_asset", mimeType: "image/png" }, depictsSystemVersionId: systemId, staleComponents: [] },
    productionFiles: [{ component: "logo", role: "Logo file", asset: { ...scope, assetId: fixtureId(500 + index), versionId: fixtureId(600 + index), contentHash: "c".repeat(64), purpose: "brand_asset", mimeType: "image/svg+xml" } }],
  });
}
export function fixtureOverview(options: { input?: IdentityInputSnapshot; systems?: IdentitySystemVersion[]; selected?: boolean } = {}): ProjectIdentityOverview {
  const input = options.input ?? fixtureInput(), systems = options.systems ?? [fixtureSystem(input)];
  const scope = { ownerId: input.ownerId, projectId: input.projectId };
  const currentBasis = getIdentityCurrentBasis({ ...scope, context: input.context, references: input.referenceSnapshot, preferences: input.preferences });
  const system = systems[0];
  const selection = options.selected && system ? selectIdentitySystem({ actorId: input.ownerId, projectId: input.projectId, system, currentInput: input,
    previousSelection: null, identityRevision: 0, request: { systemVersionId: system.id, expectedProjectRevision: input.projectRevision,
      expectedReferenceRevision: input.referenceSnapshot.referenceRevision, expectedPreferencesRevision: input.preferencesRevision, expectedIdentityRevision: 0, acceptEarlierBasis: true }, selectionId: fixtureId(700), now: fixtureAt }) : null;
  return projectIdentityOverviewSchema.parse({ ...scope, saveAvailability: { status: "available" },
    project: { id: input.projectId, owner_id: input.ownerId, title: "Local fixture Cedar", scope: input.scope, current_revision: input.projectRevision, created_at: fixtureAt, context: input.context },
    session: selection ? { ...scope, identityRevision: 1, currentSelectionId: selection.id, currentPreferencesRevision: 0, createdAt: fixtureAt, updatedAt: fixtureAt } : null,
    preferences: null, referenceSnapshot: input.referenceSnapshot, readiness: getIdentityReadiness(input.context, input.scope, input.referenceSnapshot), currentBasis,
    currentSelection: selection && system ? { selection, system, freshness: getIdentityFreshness(system.input.basis, currentBasis) } : null,
    systems: { ...scope, query: { limit: 20 }, items: [...systems].sort((left, right) => right.id.localeCompare(left.id)).map(item => summarizeIdentitySystem(item, currentBasis)), nextCursor: null },
  });
}
export function fixtureRefinement(overview: ProjectIdentityOverview, base: IdentitySystemVersion, request: RefineIdentityComponent) {
  const input = createIdentityInputSnapshot({ ownerId: overview.ownerId, projectId: overview.projectId, scope: overview.project.scope,
    projectRevision: overview.project.current_revision, context: overview.project.context, referenceSnapshot: overview.referenceSnapshot,
    preferencesRevision: overview.preferences?.revision ?? 0, preferences: overview.preferences?.preferences ?? initialIdentityPreferences(overview.project.context), capturedAt: fixtureAt });
  return refineIdentityComponent({ actorId: overview.ownerId, projectId: overview.projectId, base, currentInput: input,
    previousSelection: overview.currentSelection?.selection ?? null, identityRevision: overview.session?.identityRevision ?? 0,
    request, systemVersionId: fixtureId(800), changeId: fixtureId(801), selectionId: fixtureId(802), now: "2026-10-04T13:00:00Z" });
}

/** Authored static PNGs rasterized by local Chromium; never model output. */
export const fixtureBoards = [{"label":"Forest study","mimeType":"image/png","width":640,"height":480,"sha256":"40323c68f0b7cd206a134dfe625289836ec7c9a8ec6ad4aacdd59412ff3c79e8","base64":""},{"label":"Coral study","mimeType":"image/png","width":640,"height":480,"sha256":"af8642867cef1f0b416555233102476bf2aac504255b7607e2868d28ff335557","base64":""},{"label":"Ink study","mimeType":"image/png","width":640,"height":480,"sha256":"a248492dd82c0f770261f9b8e3c9ae9089bdf308de7dafadefe9a6d9e680dce7","base64":""}] as const;

/** Three synthetic saved names exercise wrapping and distinct boards, not generation. */
export function fixtureVisualSystems() {
  const names = [
    "Cedar Cooperative for Independent Architecture and Thoughtful Everyday Objects",
    "Cedar Botanical Research and Community Learning Studio — Coral Collection",
    "Cedar Observatory for Cultural Publishing and Long-Form Editorial Practice",
  ];
  return names.map((name,index) => {
    const system=fixtureSystem(fixtureInput({name:`Synthetic fixture — ${name}`}),index);
    return identitySystemVersionSchema.parse({...system,source:{...system.source,batchId:fixtureId(410+index),jobId:fixtureId(420+index)}});
  });
}
